SW1-2-First-Launch/solution/ProfileHeade.content:
import SwiftUI

struct ProfileHeader: View {
    let title: String

    var body: some View {
        VStack(spacing: 12) {
            Image(systemName: "paperplane.fill")
                .foregroundStyle(Color("ProfileAccent"))
                .accessibilityHidden(true)
            Text(title)
                .font(.title)
                .accessibilityIdentifier("launch-title")
            Text("Flight journal")
                .font(.subheadline)
        }
    }
}

SW1-2-First-Launch/solution/Tests/FirstL.content:
import XCTest

final class FirstLaunchUITests: XCTestCase {
    func testLaunchShowsTheExpectedHeading() {
        let app = XCUIApplication()
        app.launch()
        let heading = app.staticTexts["launch-title"]
        XCTAssertTrue(heading.waitForExistence(timeout: 10))
        XCTAssertEqual(heading.label, "First verified launch")
        XCTAssertTrue(app.staticTexts["Flight journal"].exists)
    }
}

